import 'package:flutter/material.dart';import '../core/chat_service.dart';
class ChatScreen extends StatefulWidget{final ChatService service;const ChatScreen({super.key,required this.service});@override State<ChatScreen> createState()=>_ChatScreenState();}
class _ChatScreenState extends State<ChatScreen>{final input=TextEditingController();@override void dispose(){input.dispose();super.dispose();}void send(){widget.service.sendMessage(input.text);input.clear();}
@override Widget build(BuildContext context){final s=widget.service,r=s.activeChat;if(r==null)return ListView(padding:const EdgeInsets.all(20),children:[const Text('Chat',style:TextStyle(fontSize:32,fontWeight:FontWeight.w800)),const SizedBox(height:20),if(s.chats.isEmpty)const Padding(padding:EdgeInsets.only(top:100),child:Column(children:[Icon(Icons.forum_outlined,size:64,color:Colors.black26),SizedBox(height:16),Text('Chưa có cuộc chat',style:TextStyle(fontSize:20,fontWeight:FontWeight.w700)),SizedBox(height:6),Text('Qua tab Social, tìm UID đang online và kết nối.')])) else ...s.chats.values.map((c)=>Card(child:ListTile(onTap:()=>s.openChat(c.id),leading:CircleAvatar(child:Text(c.peer.username.substring(0,1).toUpperCase())),title:Text('@${c.peer.username}'),subtitle:Text(c.messages.isEmpty?'Đã kết nối':(c.messages.last.fileName??c.messages.last.text),maxLines:1,overflow:TextOverflow.ellipsis),trailing:c.unread>0?Badge(label:Text('${c.unread}')):null))) ]);
return Column(children:[Padding(padding:const EdgeInsets.fromLTRB(12,10,12,8),child:Row(children:[IconButton(onPressed:(){s.showChatList();},icon:const Icon(Icons.arrow_back)),CircleAvatar(child:Text(r.peer.username.substring(0,1).toUpperCase())),const SizedBox(width:10),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('@${r.peer.username}',style:const TextStyle(fontSize:17,fontWeight:FontWeight.w700)),Text(r.peerOnline?'Online':'Đang reconnect...',style:TextStyle(fontSize:12,color:r.peerOnline?Colors.green:Colors.orange))])),PopupMenuButton(onSelected:(v){if(v=='close')s.closeChat(r.id);},itemBuilder:(_)=>const [PopupMenuItem(value:'close',child:Text('Kết thúc chat'))])])),const Divider(height:1),Expanded(child:ListView.builder(reverse:true,padding:const EdgeInsets.all(14),itemCount:r.messages.length,itemBuilder:(context,i){final m=r.messages[r.messages.length-1-i];return Align(alignment:m.mine?Alignment.centerRight:Alignment.centerLeft,child:Container(constraints:BoxConstraints(maxWidth:MediaQuery.sizeOf(context).width*.76),margin:const EdgeInsets.symmetric(vertical:4),padding:const EdgeInsets.symmetric(horizontal:14,vertical:10),decoration:BoxDecoration(color:m.mine?Theme.of(context).colorScheme.primary:Colors.white,borderRadius:BorderRadius.circular(18)),child:m.fileName!=null?Row(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.insert_drive_file,color:m.mine?Colors.white:Colors.black54),const SizedBox(width:8),Flexible(child:Text('${m.fileName}\n${m.fileSize??0} bytes',style:TextStyle(color:m.mine?Colors.white:Colors.black87))) ]):Text(m.text,style:TextStyle(color:m.mine?Colors.white:Colors.black87,fontSize:16)))));})),Padding(padding:EdgeInsets.fromLTRB(8,8,8,8+MediaQuery.viewInsetsOf(context).bottom),child:Row(children:[IconButton(onPressed:s.pickAndSendFile,icon:const Icon(Icons.attach_file)),Expanded(child:TextField(controller:input,onSubmitted:(_)=>send(),maxLength:2000,decoration:InputDecoration(counterText:'',hintText:'Tin nhắn...',filled:true,border:OutlineInputBorder(borderRadius:BorderRadius.circular(24),borderSide:BorderSide.none)))),IconButton(onPressed:send,icon:const Icon(Icons.send))]))]);}}
